import random,time
class Ref:
    def __init__(s,cap): s.cap=cap; s.d={}; s.t=0
    def get(s,k):
        if k not in s.d: return None
        v,f,_=s.d[k]; s.t+=1; s.d[k]=(v,f+1,s.t); return v
    def put(s,k,v):
        if s.cap==0: return
        s.t+=1
        if k in s.d: _,f,_=s.d[k]; s.d[k]=(v,f+1,s.t); return
        if len(s.d)>=s.cap:
            ev=min(s.d,key=lambda x:(s.d[x][1],s.d[x][2])); del s.d[ev]
        s.d[k]=(v,1,s.t)
random.seed(9); c=LFUCache(50); r=Ref(50)
for i in range(20000):
    k=random.randint(0,120)
    if random.random()<0.5: v=random.randint(0,9); c.put(k,v); r.put(k,v)
    else: assert c.get(k)==r.get(k),(i,k)
